const ELITE_CLUBS = [
  "Real Madrid", "FC Barcelona", "Barcelona", "Manchester City",
  "Bayern Munich", "FC Bayern München", "Paris Saint-Germain", "Liverpool FC", "Arsenal FC",
  "Chelsea FC", "Manchester United", "FC Internazionale", "Inter Miami",
];

const HIGH_REPUTATION_CLUBS = [
  "Atlético De Madrid", "Tottenham Hotspur", "Borussia Dortmund",
  "Bayer 04 Leverkusen", "Juventus", "AC Milan", "Milan", "SL Benfica",
  "FC Porto", "Napoli", "AS Roma", "Olympique Marseille", "RB Leipzig",
  "Sporting CP", "Newcastle United", "Aston Villa", "Al Hilal", "Al Nassr",
];

const GLOBAL_SUPERSTAR_RATINGS: Record<string, number> = {
  "Lionel Messi": 97,
  "Kylian Mbappe": 96,
  "Erling Haaland": 96,
  "Vinicius Junior": 95,
  "Jude Bellingham": 95,
  "Lamine Yamal": 95,
  "Harry Kane": 95,
  "Cristiano Ronaldo": 95,
};

function clamp(value: number, minimum = 50, maximum = 99) {
  return Math.max(minimum, Math.min(maximum, Math.round(value)));
}

function clubReputationBonus(club: string) {
  if (ELITE_CLUBS.some((name) => club.includes(name))) return 10;
  if (HIGH_REPUTATION_CLUBS.some((name) => club.includes(name))) return 7;
  if (/\((ENG|ESP|GER|ITA|FRA|POR|NED|BRA|ARG)\)$/.test(club)) return 4;
  return 2;
}

export function generatePlayerRatings(
  player: Pick<OfficialPlayerSeed, "name" | "position" | "club" | "caps" | "goals">,
) {
  const capsBonus = Math.min(8, player.caps * 0.06);
  const goalsMultiplier: Record<PlayerPosition, number> = {
    GK: 0.02,
    DF: 0.08,
    MF: 0.14,
    FW: 0.2,
  };
  const goalsCap: Record<PlayerPosition, number> = {
    GK: 1,
    DF: 4,
    MF: 7,
    FW: 10,
  };
  const goalsBonus = Math.min(
    goalsCap[player.position],
    player.goals * goalsMultiplier[player.position],
  );
  const positionBonus = player.position === "FW" ? 0 : 1;
  const calculated =
    65 + capsBonus + goalsBonus + clubReputationBonus(player.club) + positionBonus;
  const superstarRating = GLOBAL_SUPERSTAR_RATINGS[player.name];
  const rating = superstarRating ?? clamp(calculated, 60, 94);

  return {
    rating,
    attack: clamp(
      rating +
        (player.position === "FW" ? 4 : player.position === "MF" ? 1 : -10) +
        Math.min(player.goals * 0.05, 3),
      45,
      99,
    ),
    midfield: clamp(
      rating +
        (player.position === "MF" ? 4 : player.position === "FW" ? -2 : -5),
      45,
      99,
    ),
    defense: clamp(
      rating +
        (player.position === "DF" ? 4 : player.position === "GK" ? 5 : player.position === "MF" ? 0 : -11),
      45,
      99,
    ),
  };
}

