const DEFAULT_DETAILED_POSITIONS: Record<PlayerPosition, DetailedPosition[]> = {
  GK: ["GK"],
  DF: ["CB"],
  MF: ["CM"],
  FW: ["ST"],
};

export function getPlayerPositions(
  player: Pick<OfficialPlayerSeed, "name" | "position">,
): DetailedPosition[] {
  return POSITION_OVERRIDES[player.name] ?? DEFAULT_DETAILED_POSITIONS[player.position];
}

export function canPlayPosition(
  player: Pick<Player, "positions">,
  position: DetailedPosition,
) {
  return player.positions.includes(position);
}

export const PLAYERS: Player[] = OFFICIAL_PLAYER_SEEDS.map((player) => ({
  ...player,
  positions: getPlayerPositions(player),
  ...generatePlayerRatings(player),
}));

export const PLAYER_NATIONS = Array.from(
  new Map(
    OFFICIAL_PLAYER_SEEDS.map((player) => [
      player.nation,
      { name: player.nation, code: player.id.slice(0, 3).toUpperCase() },
    ]),
  ).values(),
);

const PLAYERS_BY_NATION = PLAYERS.reduce((playersByNation, player) => {
  const nationPlayers = playersByNation.get(player.nation) ?? [];
  nationPlayers.push(player);
  playersByNation.set(player.nation, nationPlayers);
  return playersByNation;
}, new Map<string, Player[]>());

export function getPlayersByNation(nation: string) {
  return PLAYERS_BY_NATION.get(nation) ?? [];
}
